package com.tnc.tnc.magic.free;

import com.tnc.tnc.adventure.*;
import com.tnc.tnc.magic.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Pig;
import net.minecraft.world.entity.projectile.Arrow;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.event.entity.living.*;
import static com.tnc.tnc.magic.free.ElementalIntent.*;

@GameTestHolder("tncacademy") @PrefixGameTestTemplate(false)
public final class SixElementGameTests {
    static ServerPlayer player(GameTestHelper h,Element element){var p=AdventureGameTests.player(h);Vec3 base=Vec3.atBottomCenterOf(h.absolutePos(new BlockPos(2,3,2)));p.setPos(base.x,h.getLevel().getMaxBuildHeight()-22,base.z);p.setYRot(0);p.setXRot(0);p.setNoGravity(true);p.setItemInHand(InteractionHand.MAIN_HAND,ElementWands.stack(ElementWands.find(element.id()+"_wand_3")));var data=MagicStone.getOrNull(p);data.setAffinity(element,3);data.setMaxMana(500);data.setMana(500);return p;}
    static Pig target(GameTestHelper h,ServerPlayer p,double x,double z){var t=new Pig(EntityType.PIG,h.getLevel());t.setNoAi(true);t.setNoGravity(true);t.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);t.setHealth(100);t.setPos(p.position().add(x,1,z));h.getLevel().addFreshEntity(t);return t;}
    static ElementalEffects.Effect effect(ServerPlayer p,Ability a,LivingEntity target){return new ElementalEffects.Effect(p,new Intent(a,0,0,0),target==null?p.position():target.position(),p.getLookAngle(),target);}
    static void clean(ServerPlayer p,LivingEntity... targets){ElementalRuntime.logout(new PlayerEvent.PlayerLoggedOutEvent(p));FreeMagicServer.logout(new PlayerEvent.PlayerLoggedOutEvent(p));for(var t:targets)t.discard();}
    @GameTest(template="building_test_empty",batch="six_no_precondition_debit") public static void prerequisitesRejectWithoutMana(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);String sacrifice=ElementalRuntime.prepare(p,900,new Intent(Ability.SACRIFICE,0,0,0));p.setHealth(4);String blood=ElementalRuntime.prepare(p,901,new Intent(Ability.BLOOD_SACRIFICE,0,0,0));int mana=MagicStone.getOrNull(p).getMana();clean(p,t);h.assertTrue(!sacrifice.isEmpty()&&!blood.isEmpty()&&mana==500,"Missing sacrifice prerequisites spent mana");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_control_attributes") public static void cursesRefreshAndCleanseRestoreAttributes(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);double before=t.getAttributeValue(Attributes.MOVEMENT_SPEED);var e=effect(p,Ability.SLOW_CURSE,t);ElementalStates.mark(e,t,Ability.SLOW_CURSE,60,1);double first=t.getAttributeValue(Attributes.MOVEMENT_SPEED);ElementalStates.mark(e,t,Ability.SLOW_CURSE,100,1);h.assertTrue(first<before&&first==t.getAttributeValue(Attributes.MOVEMENT_SPEED),"Curse stacked attribute penalties");ElementalStates.cleanse(t);double restored=t.getAttributeValue(Attributes.MOVEMENT_SPEED);clean(p,t);h.assertTrue(Math.abs(restored-before)<.00001,"Cleanse did not restore speed");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_armor_expiry") public static void armorErosionExpiresWithoutEquipmentMutation(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);t.getAttribute(Attributes.ARMOR).setBaseValue(12);ElementalStates.mark(effect(p,Ability.ARMOR_EROSION,t),t,Ability.ARMOR_EROSION,15,1);h.assertTrue(t.getArmorValue()==8,"Armor curse not applied");h.runAfterDelay(20,()->{int armor=t.getArmorValue();clean(p,t);h.assertTrue(armor==12,"Armor not restored after expiry");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_heal_lock") public static void healLockReducesHealingAndCleanseRemovesIt(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);ElementalStates.mark(effect(p,Ability.HEAL_LOCK,t),t,Ability.HEAL_LOCK,60,1);t.setHealth(50);t.heal(10);float locked=t.getHealth();ElementalStates.cleanse(t);t.heal(10);float healed=t.getHealth();clean(p,t);h.assertTrue(Math.abs(locked-53.5)<.01&&Math.abs(healed-63.5)<.01,"Heal lock/cleanse did not affect actual healing");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_link_recursion") public static void painLinkPropagatesOnce(GameTestHelper h){var p=player(h,Element.DARK);var a=target(h,p,0,5);var b=target(h,p,2,5);var e=effect(p,Ability.PAIN_LINK,a);ElementalStates.mark(e,a,Ability.PAIN_LINK,80,1);ElementalStates.mark(e,b,Ability.PAIN_LINK,80,1);a.hurt(h.getLevel().damageSources().playerAttack(p),8);float da=100-a.getHealth(),db=100-b.getHealth();clean(p,a,b);h.assertTrue(da==8&&db==2,"Pain link recursively propagated or failed: "+da+"/"+db);h.succeed();}
    @GameTest(template="building_test_empty",batch="six_erosion_owned") public static void devourConsumesOnlyOwnErosion(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);var e=effect(p,Ability.EROSION,t);for(int i=0;i<8;i++)ElementalStates.mark(e,t,Ability.EROSION,100,2);h.assertTrue(ElementalStates.get(p,t,Ability.EROSION).stacks==3,"Erosion exceeded three stacks");ElementalStates.consume(p,t,Ability.EROSION);boolean gone=ElementalStates.get(p,t,Ability.EROSION)==null;clean(p,t);h.assertTrue(gone,"Erosion not consumed");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_return_anchor") public static void returnMarkRemainsAtOriginalPosition(GameTestHelper h){var p=player(h,Element.LIGHTNING);Vec3 original=p.position();var e=effect(p,Ability.THUNDER_RETURN,null);LightningMagicEngine.returnPoint(e,Ability.THUNDER_RETURN);p.setPos(original.add(6,0,0));ElementalStates.tick();Vec3 anchor=ElementalStates.get(p,p,Ability.THUNDER_RETURN).anchor;clean(p);h.assertTrue(anchor.distanceToSqr(original)<.001,"Return mark followed player instead of staying behind");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_wall_projectile") public static void windWallDeflectsAfterArrowEntersPlane(GameTestHelper h){var p=player(h,Element.WIND);var t=target(h,p,0,6);var e=effect(p,Ability.WIND_WALL,null);e.at=p.position().add(0,1,4);e.axis=new Vec3(0,0,1);var arrow=new Arrow(h.getLevel(),t);arrow.setPos(e.at.add(0,0,3));arrow.setDeltaMovement(0,0,-1);h.getLevel().addFreshEntity(arrow);WindMagicEngine.deflect(e,false);h.assertTrue(arrow.getDeltaMovement().z<0,"Arrow outside wall plane deflected early");arrow.setPos(e.at.add(0,0,.5));WindMagicEngine.deflect(e,false);boolean deflected=arrow.getDeltaMovement().z>0;arrow.discard();clean(p,t);h.assertTrue(deflected,"Arrow first detected away from plane was never deflected later");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_dash_collision") public static void dashCannotCrossSolidWall(GameTestHelper h){var p=player(h,Element.WIND);BlockPos wall=p.blockPosition().offset(0,0,3);for(int y=0;y<3;y++)h.getLevel().setBlockAndUpdate(wall.above(y),Blocks.STONE.defaultBlockState());double z=p.getZ();WindMagicEngine.dash(p,10,new Vec3(0,0,1));double moved=p.getZ()-z;for(int y=0;y<3;y++)h.getLevel().setBlockAndUpdate(wall.above(y),Blocks.AIR.defaultBlockState());clean(p);h.assertTrue(moved>0&&moved<3,"Dash crossed wall: "+moved);h.succeed();}
    @GameTest(template="building_test_empty",batch="six_stone_expiry") public static void temporaryRockCollidesThenExpires(GameTestHelper h){var p=player(h,Element.EARTH);BlockPos at=p.blockPosition().offset(3,0,0);h.assertTrue(TemporaryRock.place(p,at,15),"Temporary rock could not be placed");h.assertTrue(!h.getLevel().getBlockState(at).getCollisionShape(h.getLevel(),at).isEmpty(),"Temporary rock lacks real collision");h.runAfterDelay(25,()->{boolean gone=h.getLevel().getBlockState(at).isAir();clean(p);h.assertTrue(gone,"Temporary rock persisted after expiry");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_stone_protection") public static void temporaryRockNeverOverwritesPlayerBlocks(GameTestHelper h){var p=player(h,Element.EARTH);BlockPos at=p.blockPosition().offset(3,0,0);h.getLevel().setBlockAndUpdate(at,Blocks.DIAMOND_BLOCK.defaultBlockState());boolean placed=TemporaryRock.place(p,at,20);boolean intact=h.getLevel().getBlockState(at).is(Blocks.DIAMOND_BLOCK);h.getLevel().setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());clean(p);h.assertTrue(!placed&&intact,"Construct replaced existing block");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_stone_ledger") public static void rockLedgerRoundTripsOwnership(GameTestHelper h){var p=player(h,Element.EARTH);BlockPos at=p.blockPosition().offset(3,0,0);TemporaryRock.place(p,at,80);var data=TemporaryRock.get(h.getLevel()).save(new net.minecraft.nbt.CompoundTag());boolean saved=data.getList("stones",10).stream().map(x->(net.minecraft.nbt.CompoundTag)x).anyMatch(x->x.getLong("pos")==at.asLong()&&x.getUUID("owner").equals(p.getUUID()));TemporaryRock.remove(h.getLevel(),at);clean(p);h.assertTrue(saved,"Expiry ledger omitted construct owner/position");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_healing_friend") public static void friendlyHealHasWindupAndOneDebit(GameTestHelper h){var p=player(h,Element.LIGHT);p.setHealth(8);String failure=ElementalRuntime.prepare(p,930,new Intent(Ability.HEAL,0,0,0));h.assertTrue(failure.isEmpty(),"Self heal failed: "+failure);h.runAfterDelay(15,()->h.assertTrue(p.getHealth()==8&&MagicStone.getOrNull(p).getMana()==500,"Heal occurred before charge"));h.runAfterDelay(40,()->{float health=p.getHealth();int mana=MagicStone.getOrNull(p).getMana();clean(p);h.assertTrue(health==14&&mana==482,"Heal did not run once through runtime: "+health+"/"+mana);h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_laser_stop") public static void laserStopsMaintenanceOnStop(GameTestHelper h){var p=player(h,Element.LIGHT);var t=target(h,p,0,7);String failure=ElementalRuntime.prepare(p,931,new Intent(Ability.LASER,0,0,0));h.assertTrue(failure.isEmpty(),failure);int[] mana={0};h.runAfterDelay(65,()->{ElementalRuntime.stop(p);mana[0]=MagicStone.getOrNull(p).getMana();h.assertTrue(t.getHealth()<100,"Laser caused no actual damage");});h.runAfterDelay(95,()->{int left=MagicStone.getOrNull(p).getMana();boolean stopped=ElementalEffects.count(p)==0;clean(p,t);h.assertTrue(stopped&&left==mana[0]&&left<484,"Stopped beam remained active or kept billing");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_dark_summons") public static void spiritsHaveCapAndSacrificeRequiresOne(GameTestHelper h){var p=player(h,Element.DARK);for(int i=0;i<6;i++){var e=effect(p,Ability.SUMMON_WRAITH,null);e.secondary=true;ElementalEffects.ACTIVE.add(e);}String full=DarkMagicEngine.requirement(p,new Intent(Ability.SUMMON_WRAITH,0,0,0),null),sacrifice=DarkMagicEngine.requirement(p,new Intent(Ability.SACRIFICE,0,0,0),null);int n=DarkMagicEngine.spirits(p).size();clean(p);h.assertTrue(n==6&&!full.isEmpty()&&sacrifice.isEmpty(),"Summon cap/prerequisite incorrect");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_pvp_disable") public static void disabledPvpRejectsHarmfulStates(GameTestHelper h){var p=player(h,Element.DARK);var other=AdventureGameTests.player(h);other.setPos(p.position().add(0,0,3));boolean old=h.getLevel().getServer().isPvpAllowed();h.getLevel().getServer().setPvpAllowed(false);boolean enemy=ElementalTargets.enemy(p,other);h.getLevel().getServer().setPvpAllowed(old);clean(p);clean(other);h.assertTrue(!enemy,"PvP disabled players still considered hostile for curses");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_buffs_consume") public static void storedChargeConsumedOncePerCast(GameTestHelper h){var p=player(h,Element.LIGHTNING);var e=effect(p,Ability.STORE_CHARGE,null);ElementalStates.mark(e,p,Ability.STORE_CHARGE,80,1.7);float first=ElementalStates.attackPower(p,Element.LIGHTNING),next=ElementalStates.attackPower(p,Element.LIGHTNING);clean(p);h.assertTrue(first>1.6&&next==1,"Stored lightning charge leaked across casts");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_cc_diminish") public static void repeatedControlHasDiminishingDuration(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);int first=ElementalStates.controlDuration(t,80),second=ElementalStates.controlDuration(t,80),third=ElementalStates.controlDuration(t,80);clean(p,t);h.assertTrue(first>second&&second>third,"Repeated controls did not diminish");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_pillar_lifts",timeoutTicks=140) public static void rockPillarLiftsEightBlocksWithRealCollision(GameTestHelper h){var p=player(h,Element.EARTH);BlockPos base=p.blockPosition().below();h.getLevel().setBlockAndUpdate(base,Blocks.STONE.defaultBlockState());p.setOnGround(false);double y=p.getY();String failure=ElementalRuntime.prepare(p,960,new Intent(Ability.ROCK_RISE,0,0,0));h.assertTrue(failure.isEmpty(),"Real ground rejected by onGround flag: "+failure);h.runAfterDelay(90,()->{double height=p.getY()-y;boolean top=h.getLevel().getBlockState(base.above(8)).is(TemporaryRock.BLOCK);int mana=MagicStone.getOrNull(p).getMana();for(var pos:TemporaryRock.owned(p,p.position(),20))TemporaryRock.remove(h.getLevel(),pos);h.getLevel().setBlockAndUpdate(base,Blocks.AIR.defaultBlockState());clean(p);h.assertTrue(height==8&&top&&mana==472,"Pillar must lift 8 real blocks, got height="+height+" mana="+mana);h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_pillar_moving") public static void movedPillarCasterIsRejectedBeforeDebit(GameTestHelper h){var p=player(h,Element.EARTH);BlockPos base=p.blockPosition().below();for(int x=0;x<=2;x++)h.getLevel().setBlockAndUpdate(base.offset(x,0,0),Blocks.STONE.defaultBlockState());String failure=ElementalRuntime.prepare(p,961,new Intent(Ability.ROCK_RISE,0,0,0));h.assertTrue(failure.isEmpty(),failure);p.setPos(p.position().add(1,0,0));h.runAfterDelay(40,()->{int mana=MagicStone.getOrNull(p).getMana();for(int x=0;x<=2;x++)h.getLevel().setBlockAndUpdate(base.offset(x,0,0),Blocks.AIR.defaultBlockState());clean(p);h.assertTrue(mana==500,"Moving away from pillar charged for no action");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_silence_cleanup") public static void silenceCarrierClearsWithOwnerLogout(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);ElementalStates.mark(effect(p,Ability.SILENCE,t),t,Ability.SILENCE,60,1);h.assertTrue(ElementalStates.silenced(t),"Silence did not block new casts");ElementalStates.removeOwner(p.getUUID());boolean leftover=ElementalStates.silenced(t);clean(p,t);h.assertTrue(!leftover,"Silence carrier remained after owner cleanup");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_blind_cleanse") public static void cleanseRemovesWholeBlindCurse(GameTestHelper h){var p=player(h,Element.DARK);var t=target(h,p,0,5);ElementalStates.mark(effect(p,Ability.BLIND,t),t,Ability.BLIND,60,1);t.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.BLINDNESS,15));ElementalStates.cleanse(t,1);ElementalStates.tick();boolean marked=ElementalStates.has(t,Ability.BLIND),blind=t.hasEffect(net.minecraft.world.effect.MobEffects.BLINDNESS);clean(p,t);h.assertTrue(!marked&&!blind,"Single cleanse removed carrier but left reapplying curse");h.succeed();}
    @GameTest(template="building_test_empty",batch="six_dynamic_light") public static void daylightCreatesAndReclaimsActualLight(GameTestHelper h){var p=player(h,Element.LIGHT);BlockPos at=p.blockPosition().above(3);TemporaryRock.illuminate(p,at);int emission=h.getLevel().getBlockState(at).getLightEmission(h.getLevel(),at);h.assertTrue(emission==15,"Daylight is not a real light source");h.runAfterDelay(45,()->{boolean gone=h.getLevel().getBlockState(at).isAir();clean(p);h.assertTrue(gone,"Daylight left permanent invisible blocks");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_silence_flying",timeoutTicks=140) public static void silenceDoesNotEraseReleasedProjectile(GameTestHelper h){var p=player(h,Element.WIND);var t=target(h,p,0,10);String failure=ElementalRuntime.prepare(p,965,new Intent(Ability.WIND_BALL,0,0,0));h.assertTrue(failure.isEmpty(),failure);h.runAfterDelay(32,()->p.addEffect(new net.minecraft.world.effect.MobEffectInstance(ElementalStates.SILENCE_EFFECT,50)));h.runAfterDelay(60,()->{float hp=t.getHealth();p.removeEffect(ElementalStates.SILENCE_EFFECT);clean(p,t);h.assertTrue(hp<100,"Silence erased a projectile that had already launched");h.succeed();});}
    @GameTest(template="building_test_empty",batch="six_channel_anchor") public static void turningBeamDoesNotCreateANewFormationOrigin(GameTestHelper h){var p=player(h,Element.LIGHT);String failure=ElementalRuntime.prepare(p,966,new Intent(Ability.LASER,0,0,0));h.assertTrue(failure.isEmpty(),failure);Vec3[] at={Vec3.ZERO};h.runAfterDelay(40,()->{at[0]=ElementalEffects.ACTIVE.stream().filter(e->e.owner==p).findFirst().orElseThrow().at;p.setYRot(90);});h.runAfterDelay(45,()->{Vec3 after=ElementalEffects.ACTIVE.stream().filter(e->e.owner==p).findFirst().orElseThrow().at;clean(p);h.assertTrue(after.distanceToSqr(at[0])<.001,"Turning the cursor teleported the already formed beam origin");h.succeed();});}
}
